   if(n.getOpcode()==MONITORENTER||n.getOpcode()==MONITOREXIT){var previous=prev(n);if(!(previous instanceof VarInsnNode v))throw new AssertionError("unknown monitor");boolean consumptionSnapshot=n.getOpcode()==MONITORENTER&&v.getOpcode()==ISTORE&&v.var==28;if(consumptionSnapshot){var anchor=previous;int budget=12;while(budget-->0&&!(anchor instanceof VarInsnNode saved&&saved.getOpcode()==ASTORE&&saved.var==26))anchor=prev(anchor);if(budget<0)throw new AssertionError("PC monitor receiver missing before consumption snapshot");}if(v.var==26||consumptionSnapshot){m.instructions.set(n,new InsnNode(POP));pcMonitors++;}else if(v.var==27){m.instructions.set(n,new InsnNode(POP));companionMonitors++;}else throw new AssertionError("unknown monitor local "+v.var);}
