  var first=prev(prev(copy));if(!(first instanceof VarInsnNode copyReceiver&&copyReceiver.var==0&&copyReceiver.getOpcode()==ALOAD))throw new AssertionError("copy receiver");var branch=consume.getNext();while(branch.getOpcode()<0)branch=branch.getNext();if(!(branch instanceof JumpInsnNode yes&&yes.getOpcode()==IFNE))throw new AssertionError("material success");remove(m,first,yes.label);
